class TestWalkForwardUtils:
    def test_resolve_latest_walk_forward_weights_prefers_most_recent_file(self, tmp_path):
        from backtesting.walk_forward import resolve_latest_walk_forward_weights

        older = tmp_path / "run_old"
        newer = tmp_path / "run_new"
        older.mkdir()
        newer.mkdir()
        older_file = older / "latest_best_weights.json"
        newer_file = newer / "champion_weights.json"
        older_file.write_text(json.dumps({"sentiment_weight": 0.1, "macro_weight": 0.1, "quant_weight": 0.8}), encoding="utf-8")
        newer_file.write_text(json.dumps({"sentiment_weight": 0.2, "macro_weight": 0.1, "quant_weight": 0.7}), encoding="utf-8")
        os.utime(older_file, (1, 1))
        os.utime(newer_file, (2, 2))

        weights = resolve_latest_walk_forward_weights([tmp_path])

        assert weights is not None
        assert weights.sentiment_weight == 0.2
        assert weights.quant_weight == 0.7


class TestBacktestingRegistry:
    def test_start_backtesting_run_rejects_duplicate_active_kind(self, monkeypatch):
        from ihm.services import backtesting_registry
        from ihm.services.backtesting_runner import BacktestRunOptions

        monkeypatch.setattr(
            backtesting_registry,
            "list_active_backtesting_runs_by_kind",
            lambda run_kind: [{"run_id": "run-active-123", "run_kind": run_kind, "status": "running"}],
        )

        try:
            backtesting_registry.start_backtesting_run(
                "run",
                "Backtest complet",
                BacktestRunOptions(start="2025-04-21", end="2025-04-14"),
            )
        except RuntimeError as exc:
            assert "déjà en cours" in str(exc)
            assert "run-active-123" in str(exc)
        else:
            raise AssertionError("Le registre aurait dû bloquer un second run du même type.")

from ihm.services.alpha_scanner_threshold_presets import ( DEFAULT_ALPHA_SCANNER_DEPENDENCY_THRESHOLDS, DEFAULT_MARKET_REGIME, DEFAULT_PRESET_STYLE, get_alpha_scanner_threshold_preset, )
def test_default_preset_matches_swing_cash_pro_normal() -> None: thresholds = get_alpha_scanner_threshold_preset(style=DEFAULT_PRESET_STYLE, market_regime=DEFAULT_MARKET_REGIME)
assert thresholds == DEFAULT_ALPHA_SCANNER_DEPENDENCY_THRESHOLDS
def test_very_selective_regime_is_stricter_than_normal_for_swing_cash_pro() -> None: normal = get_alpha_scanner_threshold_preset(style="swing_cash_pro", market_regime="normal") very_selective = get_alpha_scanner_threshold_preset(style="swing_cash_pro", market_regime="very_selective")
assert very_selective["sync_latest_quotes"]["coverage_warn_pct"] > normal["sync_latest_quotes"]["coverage_warn_pct"] assert very_selective["sync_latest_quotes"]["max_age_error_days"] < normal["sync_latest_quotes"]["max_age_error_days"] assert very_selective["sync_earnings_calendar"]["min_horizon_warn_days"] > normal["sync_earnings_calendar"]["min_horizon_warn_days"]
def test_tolerant_style_is_more_permissive_than_swing_cash_pro_in_normal_market() -> None: strict = get_alpha_scanner_threshold_preset(style="swing_cash_pro", market_regime="normal") tolerant = get_alpha_scanner_threshold_preset(style="tolerant", market_regime="normal")
assert tolerant["sync_latest_quotes"]["coverage_warn_pct"] < strict["sync_latest_quotes"]["coverage_warn_pct"] assert tolerant["sync_latest_quotes"]["max_age_error_days"] > strict["sync_latest_quotes"]["max_age_error_days"] assert tolerant["sync_earnings_calendar"]["min_horizon_error_days"] < strict["sync_earnings_calendar"]["min_horizon_error_days"]

from ihm.services.run_summary import aggregate_workflow_run_summary, build_latest_run_summary_rows, build_run_summary_caption


def test_aggregate_workflow_run_summary_merges_numeric_and_nested_counters() -> None:
    aggregated = aggregate_workflow_run_summary(
        [
            {
                "run_id": "run-import",
                "step_key": "import_alpaca_bar",
                "step_label": "1. Import",
                "status": "completed",
                "run_summary": {
                    "targeted_symbols": 3,
                    "successful_symbols": 2,
                    "max_calendar_gap_days": 8,
                    "history_status_counts": {"ready": 2, "provider_error": 1},
                },
            },
            {
                "run_id": "run-sanitize",
                "step_key": "data_sanitizer_daily",
                "step_label": "2. Sanitize",
                "status": "completed",
                "run_summary": {
                    "targeted_symbols": 3,
                    "successful_symbols": 3,
                    "max_calendar_gap_days": 2,
                    "status_breakdown": {"success": 3, "failed": 0},
                },
            },
        ]
    )

    assert aggregated["workflow_steps_with_summary"] == 2
    assert aggregated["targeted_symbols"] == 6
    assert aggregated["successful_symbols"] == 5
    assert aggregated["max_calendar_gap_days"] == 8
    assert aggregated["history_status_counts"] == {"ready": 2, "provider_error": 1}
    assert aggregated["status_breakdown"] == {"success": 3, "failed": 0}
    assert len(aggregated["workflow_step_summaries"]) == 2


